-- C11 / P11.10 — scalable recovery/archive/export/provider-migration evidence with provenance-preserving missing/reconstructed artifact states.
create table if not exists public.command_center_book_recovery_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 recovery_event_id text not null check(btrim(recovery_event_id)<>''), book_id text not null check(btrim(book_id)<>''), project_id text not null check(btrim(project_id)<>''), canonical_title text not null check(btrim(canonical_title)<>''), aliases text[] not null default '{}'::text[], series_root_id text, series_sequence integer, status text not null check(status in ('active','dormant','archived')), source_refs text[] not null check(cardinality(source_refs)>0), artifact_refs text[] not null default '{}'::text[], missing_artifact_kinds text[] not null default '{}'::text[], continuity_refs text[] not null default '{}'::text[], recovered_at timestamptz not null,
 primary key(owner_id,recovery_event_id), unique(owner_id,book_id,recovered_at), check(series_root_id is null or btrim(series_root_id)<>''), check((series_sequence is null and series_root_id is null) or (series_sequence is not null and series_sequence>0 and series_root_id is not null))
);
create table if not exists public.command_center_book_recovered_artifact_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 artifact_event_id text not null check(btrim(artifact_event_id)<>''), artifact_id text not null check(btrim(artifact_id)<>''), book_id text not null check(btrim(book_id)<>''), kind text not null check(btrim(kind)<>''), state text not null check(state in ('present','missing','recovered_original','reconstructed')), artifact_ref text, content_hash text, source_refs text[] not null check(cardinality(source_refs)>0), reconstruction_refs text[] not null default '{}'::text[], observed_at timestamptz not null,
 primary key(owner_id,artifact_event_id), unique(owner_id,artifact_id,observed_at), check((state='missing' and artifact_ref is null and content_hash is null) or (state<>'missing' and artifact_ref is not null and btrim(artifact_ref)<>'' and content_hash is not null and btrim(content_hash)<>'')), check((state='reconstructed' and cardinality(reconstruction_refs)>0) or state<>'reconstructed')
);
create table if not exists public.command_center_book_archive_transition_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 transition_event_id text not null check(btrim(transition_event_id)<>''), transition_id text not null check(btrim(transition_id)<>''), project_id text not null check(btrim(project_id)<>''), book_id text not null check(btrim(book_id)<>''), from_status text not null check(from_status in ('active','dormant','archived')), to_status text not null check(to_status in ('active','dormant','archived')), owner_action_ref text not null check(btrim(owner_action_ref)<>''), observed_at timestamptz not null,
 primary key(owner_id,transition_event_id), unique(owner_id,transition_id), check(from_status<>to_status)
);
create table if not exists public.command_center_book_export_manifest_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 export_event_id text not null check(btrim(export_event_id)<>''), export_id text not null check(btrim(export_id)<>''), project_ids text[] not null check(cardinality(project_ids)>0), book_ids text[] not null check(cardinality(book_ids)>0), artifact_ids text[] not null default '{}'::text[], provider_keys text[] not null default '{}'::text[], manifest_hash text not null check(btrim(manifest_hash)<>''), source_refs text[] not null check(cardinality(source_refs)>0), created_at timestamptz not null,
 primary key(owner_id,export_event_id), unique(owner_id,export_id)
);
create table if not exists public.command_center_book_provider_migration_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 migration_event_id text not null check(btrim(migration_event_id)<>''), migration_id text not null check(btrim(migration_id)<>''), project_id text not null check(btrim(project_id)<>''), book_id text not null check(btrim(book_id)<>''), from_provider_key text not null check(btrim(from_provider_key)<>''), to_provider_key text not null check(btrim(to_provider_key)<>''), state text not null check(state in ('planned','exported','imported','verified','blocked')), export_manifest_id text not null check(btrim(export_manifest_id)<>''), evidence_refs text[] not null check(cardinality(evidence_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,migration_event_id), unique(owner_id,migration_id), check(from_provider_key<>to_provider_key)
);
create or replace view public.command_center_book_recovery_current with (security_invoker=true) as select distinct on(owner_id,book_id) owner_id,recovery_event_id,book_id,project_id,canonical_title,aliases,series_root_id,series_sequence,status,source_refs,artifact_refs,missing_artifact_kinds,continuity_refs,recovered_at from public.command_center_book_recovery_history order by owner_id,book_id,recovered_at desc;
create or replace function public.command_center_reject_book_recovery_evidence_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Book recovery evidence is immutable'; end $$;
drop trigger if exists command_center_book_recovery_immutable on public.command_center_book_recovery_history; create trigger command_center_book_recovery_immutable before update or delete on public.command_center_book_recovery_history for each row execute function public.command_center_reject_book_recovery_evidence_mutation();
drop trigger if exists command_center_book_recovered_artifact_immutable on public.command_center_book_recovered_artifact_history; create trigger command_center_book_recovered_artifact_immutable before update or delete on public.command_center_book_recovered_artifact_history for each row execute function public.command_center_reject_book_recovery_evidence_mutation();
drop trigger if exists command_center_book_archive_transition_immutable on public.command_center_book_archive_transition_history; create trigger command_center_book_archive_transition_immutable before update or delete on public.command_center_book_archive_transition_history for each row execute function public.command_center_reject_book_recovery_evidence_mutation();
drop trigger if exists command_center_book_export_manifest_immutable on public.command_center_book_export_manifest_history; create trigger command_center_book_export_manifest_immutable before update or delete on public.command_center_book_export_manifest_history for each row execute function public.command_center_reject_book_recovery_evidence_mutation();
drop trigger if exists command_center_book_provider_migration_immutable on public.command_center_book_provider_migration_history; create trigger command_center_book_provider_migration_immutable before update or delete on public.command_center_book_provider_migration_history for each row execute function public.command_center_reject_book_recovery_evidence_mutation();
alter table public.command_center_book_recovery_history enable row level security; alter table public.command_center_book_recovered_artifact_history enable row level security; alter table public.command_center_book_archive_transition_history enable row level security; alter table public.command_center_book_export_manifest_history enable row level security; alter table public.command_center_book_provider_migration_history enable row level security;
revoke all on table public.command_center_book_recovery_history,public.command_center_book_recovered_artifact_history,public.command_center_book_archive_transition_history,public.command_center_book_export_manifest_history,public.command_center_book_provider_migration_history from public,anon,authenticated; grant select,insert on table public.command_center_book_recovery_history,public.command_center_book_recovered_artifact_history,public.command_center_book_archive_transition_history,public.command_center_book_export_manifest_history,public.command_center_book_provider_migration_history to authenticated; grant select on table public.command_center_book_recovery_current to authenticated;
create policy p11_10_book_recovery_owner on public.command_center_book_recovery_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_10_book_recovered_artifact_owner on public.command_center_book_recovered_artifact_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_10_book_archive_transition_owner on public.command_center_book_archive_transition_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_10_book_export_manifest_owner on public.command_center_book_export_manifest_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_10_book_provider_migration_owner on public.command_center_book_provider_migration_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
